   // Compare with our known selector\n    let transferSelector = getSelector();\n    if (selector == transferSelector) {\n      // This is a transfer call\n      return;\n    }\n  }\n\n  return;\n}\n',"optimizations/constant-folding.bug":"name Optimizations;\n\nstorage {\n  [0] result: uint256;\n}\n\ncode {\n  // Constant folding example\n  let a = 10 + 20;      // Should fold to 30\n  let b = a * 2;        // After constant prop, should fold to 60\n  let c = 100 - 40;     // Should fold to 60\n\n  // This comparison should be folded\n  if (a > 25) {         // 30 > 25 = true, always taken\n    result = b + c;     // 60 + 60 = 120\n    /*@test constant-folding-result\n    fails: constant comparison folding not implemented\n    variables:\n      result:\n        pointer: { location: storage, slot: 0 }\n        value: 120\n    */\n  } else {\n    // Dead code - should be eliminated\n    result = 999;\n  }\n}\n","optimizations/cse-simple.bug":"name CSESimple;\n\nstorage {\n  [0] value: uint256;\n  [1] result: uint256;\n}\n\ncode {\n  // Simple CSE within a single basic block\n  // These should get deduplicated\n  let a = value * 2;\n  let b = value * 2;  // Same computation as line 11\n  let c = value * 2;  // Same computation as line 11\n\n  result = a + b + c;\n}\n\n/*@test cse-with-zero-value\nafter: call\nstorage:\n  0: 0\n  1: 0\n*/\n","optimizations/cse.bug":"name CSEDemo;\n\nstorage {\n  [0] values: mapping<address, uint256>;\n  [1] result: uint256;\n}\n\ncreate {\n  let userValue = values[msg.sender];\n\n  if (userValue > 100) {\n    result = values[msg.sender] * 2;\n  } else {\n    result = values[msg.sender] + msg.value;\n  }\n}\n","wip/returndata.bug":'// @wip\nname ReturnDataAccess;\n\n// Example 16: Return Data Access\n//\n// Expected IR (simplified):\n//   %result = call function="external", target=%other_contract, ...\n//   %success = extract_field %result, 0  // Extract success flag\n//   %return_val = read location="returndata", offset=0, length=32\n/